//! Android entry point generated by `recomp android`.
//! Wraps the emitted `main` so it can run inside an Android app via JNI.
#![allow(dead_code, unused_imports, unused_mut, unused_variables)]

mod generated;

use jni::objects::{JClass, JString};
use jni::sys::jint;
use jni::JNIEnv;
use std::fs::File;
use std::io::Write;
use std::os::unix::io::AsRawFd;

extern "C" {
    fn dup2(oldfd: i32, newfd: i32) -> i32;
}

#[no_mangle]
pub extern "system" fn Java_org_switchrecomp_android_RecompActivity_nativeRun(
    mut env: JNIEnv,
    _class: JClass,
    work_dir: JString,
    log_path: JString,
) -> jint {
    let work_dir: String = match env.get_string(&work_dir) {
        Ok(value) => value.into(),
        Err(_) => return -2,
    };
    let log_path: String = match env.get_string(&log_path) {
        Ok(value) => value.into(),
        Err(_) => return -2,
    };
    let mut log = match File::create(&log_path) {
        Ok(file) => file,
        Err(_) => return -3,
    };
    unsafe {
        dup2(log.as_raw_fd(), 1);
        dup2(log.as_raw_fd(), 2);
    }
    if let Err(err) = std::env::set_current_dir(&work_dir) {
        let _ = writeln!(log, "failed to enter {work_dir}: {err}");
        return -4;
    }

    let code = match std::panic::catch_unwind(generated::main) {
        Ok(Ok(())) => {
            println!("recomp exit: ok");
            0
        }
        Ok(Err(err)) => {
            println!("recomp exit: error: {err}");
            1
        }
        Err(_) => {
            println!("recomp exit: panic");
            101
        }
    };
    let _ = std::io::stdout().flush();
    let _ = std::io::stderr().flush();
    code
}
